# L — Liskov Substitution Principle
# Los subtipos deben ser sustituibles por sus tipos base.

class Rectangulo:
    def __init__(self, ancho: float, alto: float):
        self._ancho = ancho
        self._alto = alto

    @property
    def ancho(self) -> float:
        return self._ancho

    @ancho.setter
    def ancho(self, valor: float) -> None:
        self._ancho = valor

    @property
    def alto(self) -> float:
        return self._alto

    @alto.setter
    def alto(self, valor: float) -> None:
        self._alto = valor

    def area(self) -> float:
        return self._ancho * self._alto

# MAL: Cuadrado viola LSP
# class Cuadrado(Rectangulo):
#     @Rectangulo.ancho.setter
#     def ancho(self, valor):
#         self._ancho = self._alto = valor  # Rompe el contrato del setter!

# BIEN: Cuadrado NO hereda de Rectangulo
class Cuadrado:
    def __init__(self, lado: float):
        self._lado = lado

    def area(self) -> float:
        return self._lado ** 2

def test_area(forma: Rectangulo) -> None:
    forma.ancho = 5
    forma.alto = 4
    assert forma.area() == 20  # Cuadrado rompería esto

r = Rectangulo(2, 3)
test_area(r)  # OK

