        self._ancho = ancho
        self._alto = alto

    @property
    def ancho(self) -> float:
        return self._ancho

    @ancho.setter
    def ancho(self, valor: float) -> None:
        self._ancho = valor

    @property
    def alto(self) -> float:
        return self._alto

    @alto.setter
    def alto(self, valor: float) -> None:
        self._alto = valor

    def area(self) -> float:
        return self._ancho * self._alto

