        self.porcentaje = porcentaje

    def aplicar(self, precio: float) -> float:
        return precio * (1 - self.porcentaje / 100)

class DescuentoFijo(Descuento):
    def __init__(self, monto: float):
        self.monto = monto

    def aplicar(self, precio: float) -> float:
        return max(0.0, precio - self.monto)

